INSERT INTO evidence_population_match
 (match_id, source_ref, ref_id, target_population, study_population, sample_size,
  match_grade, mismatch_note, gap_id, created_at, created_by_session)
VALUES
 ('EPM-00945-A','REF-00945','REF-00945','MOB','Community-dwelling people aged 75-81, Finland; general older cohort, not selected for disability',589,
  'PROXY','Population of STUDY is a general older-age cohort, not a disabled cohort. Served population is people with elevated sustained-exertion demand (AX-STA). Age-related walking difficulty overlaps that demand but is not identical to it, and the study did not disaggregate disabled participants. PROXY, not EXACT.',NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating'),

 ('EPM-00946-A','REF-00946','REF-00946','MOB','Community-dwelling people aged 75-81 all able to walk at least 500m at baseline, Finland; subgroup with self-reported walking difficulties',643,
  'PARTIAL','Closer than REF-00945 because the paper explicitly reports the resting-places association as STRONGER in the subgroup with walking difficulties, which is the served demand. Still PARTIAL not EXACT: the subgroup is defined by self-reported difficulty within an age cohort, not by disability, and everyone could walk 500m at entry, so people with the highest sustained-exertion demand are excluded by the sampling frame.',NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating'),

 ('EPM-00947-A','REF-00947','REF-00947','MOB','Adults 50-86 using mobility assistive devices (canes 57%, walkers 57%, wheelchairs 46%), King County WA, US',35,
  'EXACT','Study population is defined by assistive-device use, i.e. by the functional demand itself rather than by age. This is the closest population match in the batch for the ambulant/wheeled portion of the served demand.',NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating'),

 ('EPM-00948-A','REF-00948','REF-00948','MOB','Community-dwelling hip-fracture patients, mean 70 days post-trauma, Finland',81,
  'PARTIAL','Post-acute hip-fracture recovery is a time-limited state with elevated sustained-exertion demand, overlapping but not equal to the served population. The finding used from this source is the NEGATIVE one (individual rehabilitation did not shift perceived environmental barriers), which transfers more readily than a positive effect estimate would.',NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating'),

 ('EPM-00952-A','REF-00952','REF-00952','MOB','Community-dwelling Norwegians aged 67+, mean age 76.1, Kristiansand; paper states the least mobile groups living in institutions are not represented; no disabled cohort',1761,
  'MISMATCH','R13 MISMATCH, RECORDED DELIBERATELY. REF-00951 (ASLA) cites this study to support a claim about "older adults AND MOBILITY-DISABLED PEOPLE". The study has no disabled cohort and explicitly excludes the least mobile. The population claim is an extrapolation the cited source does not license. This row exists so the corpus records the mismatch rather than inheriting the extrapolation.','GAP-304',
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating');

-- ---------- search_candidates (R7 off-slug/unverified -> structured, not prose; R15 hypotheses) ----------
INSERT INTO search_candidates
 (exec_id, found_under_slug, suggested_slug, disposition, title, locator, locator_status,
  tier_guess, harm_finding, why_not_admitted, notes, session, created_at)
SELECT x.exec_id,'energy-conservation-rest-points-seating',s.sug,s.disp,s.title,s.loc,s.locst,s.tier,s.harm,s.why,s.note,
       'session_2026-07-25-energy-conservation-rest-points-seating','2026-07-25'
FROM (SELECT exec_id FROM search_executions
      WHERE session='session_2026-07-25-energy-conservation-rest-points-seating'
        AND query_text LIKE 'lived experience of disabled people%') x
CROSS JOIN (
  SELECT 'energy-conservation-rest-points-seating' AS sug,'PENDING-VERIFICATION' AS disp,
         'Inclusive Streetscapes: Embedding disabled people''s lived experience into street accessibility (Ulahannan et al.)' AS title,
         'https://www.sciencedirect.com/science/article/pii/S2666558125000272' AS loc,'UNVERIFIED' AS locst,
         3 AS tier,0 AS harm,
         'Surfaced via Consensus, which returns no DOI. R10 requires re-retrieval through a locator ladder before admission; not completed this batch.' AS why,
         'HYPOTHESIS (R15): described from the Consensus abstract only as 26 semi-structured interviews with disabled people in the UK on streetscape barriers. Must be re-described from the source on resolution. Whether it addresses seating specifically is NOT yet established.' AS note
  UNION ALL SELECT 'energy-conservation-rest-points-seating','PENDING-VERIFICATION',
         'Pedestrianisation and Disabled People: A study of personal mobility in Kingston town centre (Gant, Disability & Society)',
         'Consensus record; DOI not returned','UNVERIFIED',3,1,
         'No DOI returned by the engine; not re-retrieved.',
         'HYPOTHESIS (R15): abstract indicates the needs of orange-badge holders for toilet facilities AND SEATING were not fully met after pedestrianisation. If confirmed this is a 1997 harm/inadequacy finding directly on this slug, and an early one. Re-describe from source on resolution.'
  UNION ALL SELECT 'energy-conservation-rest-points-seating','PENDING-VERIFICATION',
         'Are We There Yet? Barriers to transport for disabled people in 2023 (Transport for All)',
         'https://www.transportforall.org.uk/wp-content/uploads/2023/12/Are-we-there-yet_Highlights_PDF-web-compressed-more-compressed.pdf','UNVERIFIED',
         NULL,1,'Not re-retrieved this batch. Co-1 status likely but must be verified from the organisation own material before classification, as was done for REF-00950.',
         'HYPOTHESIS (R15): search snippet indicates only 4% of respondents reported no barriers. Whether the report addresses seating or rest points specifically is UNKNOWN and must not be assumed.'
  UNION ALL SELECT 'energy-conservation-rest-points-seating','PENDING-VERIFICATION',
         'Inclusive Design in Town Centres and Busy Street Areas, Appendix C: Perspectives of disabled street users (Transport Scotland)',
         'https://www.transport.gov.scot/publication/inclusive-design-in-town-centres-and-busy-street-areas/appendix-c-perspectives-of-disabled-street-users-on-inclusive-physical-design/','UNVERIFIED',
         5,0,'Not re-retrieved this batch.',
         'HYPOTHESIS (R15): a national framework carrying a disabled-street-user focus-group appendix. Snippet suggests it recommends regular rest locations with a variety of seating options, sited outside the pedestrian corridor. Would be a second jurisdiction (Scotland) on the interval question. Verify whether it states an interval figure.'
  UNION ALL SELECT 'energy-conservation-rest-points-seating','PENDING-VERIFICATION',
         'Seating in Aged Care: Physical fit, independence and comfort (Blackler et al., SAGE Open Medicine)','2018; cited in REF-00950 reference list','UNVERIFIED',3,0,
         'R2 backward-mining lead from REF-00950; not yet resolved to a locator.',
         'HYPOTHESIS (R15): cited by the Co-1 guidance as an evidence source for seat dimensions. If it is primary research on seat fit it may be the closest thing to a primary basis for the height figures, which currently rest on standards. Re-describe on resolution.'
  UNION ALL SELECT 'energy-conservation-rest-points-seating','PENDING-VERIFICATION',
         'Benches and Seating in Public Spaces (Access Association)','https://accessassociation.co.uk/2024/10/30/benches-and-seating-in-public-spaces/','UNVERIFIED',3,0,
         'Not re-retrieved this batch.',
         'HYPOTHESIS (R15): professional access-officer body, so likely T3-grey or T2 standard_eb rather than Co-1. Classification must be decided from the source, not from the organisation name.'
) s;

COMMIT;
